package com.jnapanam.sportszone.notification.controller;import com.jnapanam.sportszone.notification.service.NotificationProviderSettingsService;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/notification-providers")@PreAuthorize("hasRole('SUPER_ADMIN')")public class NotificationProviderSettingsController{private final NotificationProviderSettingsService s;public NotificationProviderSettingsController(NotificationProviderSettingsService s){this.s=s;}@GetMapping public Map<String,Object> get(){return s.masked();}@PutMapping public Map<String,Object> put(Authentication a,@RequestBody Map<String,Object>b){s.save(UUID.fromString(a.getName()),b);return s.masked();}}
